package mclite;
public class QuickApi { public static void main(String[] a) throws Exception { Log.init(java.nio.file.Path.of("/tmp/quickapi.log")); var m=new Modrinth(ProgressSink.NOOP,new CancellationToken()); for (String v: new String[]{"26.3","1.21.4","1.20.1"}) { try { var r=m.search("", "mod", v, "fabric"); System.out.println(v+" -> "+r.size()+(r.isEmpty()?"":" "+r.get(0).title())); } catch(Exception e){System.out.println(v+" ERR "+e);} } var p=m.search("Fabric API","mod","1.20.1","fabric"); System.out.println("fabric api "+p.size()); if(!p.isEmpty()){var vs=m.versions(p.get(0).id(),"1.20.1","fabric"); System.out.println("versions "+vs.size()+" first="+(vs.isEmpty()?"":vs.get(0).versionNumber()));} } }
